// *** EDIT THIS NODE ***
// 1. FINKFOLD_CALLBACK_URL:
//    Production: https://yourdomain.com/api/whatsapp-reply
//    Local dev:  https://xxxx.ngrok-free.app/api/whatsapp-reply  (use ngrok)
const FINKFOLD_CALLBACK_URL = "PASTE_FINKFOLD_CALLBACK_URL_HERE";

// 2. FINKFOLD_SECRET: Same value as N8N_ATTENDANCE_WEBHOOK_SECRET in your .env.local
const FINKFOLD_SECRET = "PASTE_YOUR_SECRET_HERE";

const item = $input.first().json;
const body = item.body || item;

// Extract message from Meta webhook payload
const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;

// Ignore status deliveries (sent, delivered, read receipts)
const messages = value?.messages;
if (!messages || messages.length === 0) {
  return [];
}

const msg = messages[0];
const rawFrom = msg.from || "";
const fromPhone = rawFrom.startsWith("+") ? rawFrom : "+" + rawFrom;
const metaMessageId = msg.id || null;

let messageType = "unknown";
let reasonPayload = null;
let messageBody = null;

if (msg.type === "interactive") {
  messageType = "interactive";
  if (msg.interactive?.type === "button_reply") {
    reasonPayload = msg.interactive.button_reply.id;
    messageBody = msg.interactive.button_reply.title;
  } else if (msg.interactive?.type === "list_reply") {
    reasonPayload = msg.interactive.list_reply.id;
    messageBody = msg.interactive.list_reply.title;
  }
} else if (msg.type === "button") {
  messageType = "interactive";
  reasonPayload = msg.button?.payload || null;
  messageBody = msg.button?.text || null;
} else if (msg.type === "text") {
  messageType = "text";
  messageBody = msg.text?.body || "";
}

return [{
  _url: FINKFOLD_CALLBACK_URL,
  _secret: FINKFOLD_SECRET,
  _payload: {
    parentPhone: fromPhone,
    messageType: messageType,
    reasonPayload: reasonPayload,
    messageBody: messageBody,
    metaMessageId: metaMessageId
  }
}];

const res = $input.first().json;
return [{
  status: res.success ? "reconciled" : "logged",
  matched: res.matched,
  autoHandled: res.autoHandled,
  reason: res.reason,
  message: res.message
}];

// *** META WEBHOOK VERIFICATION TOKEN ***
// In Meta App Dashboard > WhatsApp > Configuration, enter:
//   Callback URL : https://your-n8n.app/webhook/whatsapp-inbound
//   Verify Token : finkfold_whatsapp_verify_token
const VERIFY_TOKEN = "finkfold_whatsapp_verify_token";

const d = $input.first().json;
const query = d.query || {};
const token = query["hub.verify_token"];
const challenge = query["hub.challenge"];

if (token === VERIFY_TOKEN) {
  return [{ challenge: challenge || "OK" }];
}
return [{ challenge: "Verification failed: token mismatch", status: 403 }];
